import sys

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return
    N = int(input_data[0])
    K = int(input_data[1])
    MOD = 10**9 + 7

    limit = int(N**0.5) + 1
    cnt = [0] * (limit + 1)
    for i in range(1, limit + 1):
        cnt[i] = 1

    for _ in range(K - 1):
        new_cnt = [0] * (limit + 1)
        for i in range(1, limit + 1):
            if cnt[i] == 0:
                continue
            j = 1
            while i * j <= N:
                if j <= limit:
                    new_cnt[j] = (new_cnt[j] + cnt[i]) % MOD
                else:
                    new_cnt[limit] = (new_cnt[limit] + cnt[i]) % MOD
                j += 1
        cnt = new_cnt

    total = 0
    for i in range(1, limit + 1):
        total = (total + cnt[i]) % MOD
    print(total)

if __name__ == "__main__":
    solve()
